// 乐观更新：先本地生效，服务端返回后确认或回滚
function createTodoStore() {
  let state = { todos: [] };
  let seq = 0;
  const pending = new Map();       // tempId -> { text }
  return {
    get state() { return state; },
    addOptimistic(text) {
      const tempId = 'tmp-' + (++seq);
      state = { todos: [...state.todos, { id: tempId, text, synced: false }] };
      pending.set(tempId, { text });
      return tempId;
    },
    confirm(tempId, serverId) {     // 成功：本地 id 换成服务端 id
      state = { todos: state.todos.map(t =>
        t.id === tempId ? { id: serverId, text: t.text, synced: true } : t) };
      pending.delete(tempId);
      return state;
    },
    rollback(tempId) {              // 失败：移除乐观条目
      if (!pending.has(tempId)) return state;
      state = { todos: state.todos.filter(t => t.id !== tempId) };
      pending.delete(tempId);
      return state;
    },
  };
}

// 用例 A：成功 -> 保留
const A = createTodoStore();
const t1 = A.addOptimistic('buy milk');
console.log('after_optimistic_count=' + A.state.todos.length);
console.log('optimistic_synced=' + A.state.todos[0].synced);
A.confirm(t1, 101);
console.log('after_confirm_ids=' + A.state.todos.map(t => t.id).join(','));
console.log('after_confirm_synced=' + A.state.todos[0].synced);
console.log('success_count_kept=' + (A.state.todos.length === 1));

// 用例 B：失败 -> 回滚
const B = createTodoStore();
const t2 = B.addOptimistic('buy eggs');
console.log('before_rollback_count=' + B.state.todos.length);
console.log('before_rollback_synced=' + B.state.todos[0].synced);
B.rollback(t2);
console.log('after_rollback_count=' + B.state.todos.length);
console.log('failure_state_restored=' + (B.state.todos.length === 0));
